# Bash completion for klyrshift. Generated by scripts/build_cli_docs.py.
# Install as /usr/share/bash-completion/completions/klyrshift.

_klyrshift() {
    local cur cmd i
    cur="${COMP_WORDS[COMP_CWORD]}"

    # The first word that is not an option is the command. Options come
    # before or after it; the ones with a value are skipped by matching
    # the value that follows them.
    cmd=""
    for ((i = 1; i < COMP_CWORD; i++)); do
        case "${COMP_WORDS[i]}" in
            --lang) ((i++)) ;;
            -*) ;;
            *) cmd="${COMP_WORDS[i]}"; break ;;
        esac
    done

    if [[ -z "$cmd" ]]; then
        COMPREPLY=( $(compgen -W "app-mode collect-logs config dict doctor explain export fix gui hotkeys import install-autostart kill learn logs mode restart start status stop undo uninstall-autostart verify version -h --help --version --lang" -- "$cur") )
        return 0
    fi

    case "$cmd" in
        app-mode)
            if [[ "$cur" != -* ]] && (( COMP_CWORD == i + 1 )); then
                COMPREPLY=( $(compgen -W "auto manual hybrid" -- "$cur") )
            else
                COMPREPLY=( $(compgen -W "--clear -h --help" -- "$cur") )
            fi
            ;;
        collect-logs)
            COMPREPLY=( $(compgen -W "--output -h --help" -- "$cur") )
            ;;
        config)
            if [[ "$cur" != -* ]] && (( COMP_CWORD == i + 1 )); then
                COMPREPLY=( $(compgen -W "show edit reset path migrate" -- "$cur") )
            else
                COMPREPLY=( $(compgen -W "--dry-run -h --help" -- "$cur") )
            fi
            ;;
        dict)
            if [[ "$cur" != -* ]] && (( COMP_CWORD == i + 1 )); then
                COMPREPLY=( $(compgen -W "list add remove download import-file categories install list-installed remove-category pack verify install-file uninstall-file" -- "$cur") )
            else
                COMPREPLY=( $(compgen -W "--lang --file --name --kind --output --package-version --license -h --help" -- "$cur") )
            fi
            ;;
        doctor)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            ;;
        explain)
            COMPREPLY=( $(compgen -W "--text --layout -h --help" -- "$cur") )
            ;;
        export)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            ;;
        fix)
            COMPREPLY=( $(compgen -W "--text --apply --dry-run -h --help" -- "$cur") )
            ;;
        gui)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            ;;
        hotkeys)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            ;;
        import)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            ;;
        install-autostart)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            ;;
        kill)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            ;;
        learn)
            if [[ "$cur" != -* ]] && (( COMP_CWORD == i + 1 )); then
                COMPREPLY=( $(compgen -W "list promote forget" -- "$cur") )
            else
                COMPREPLY=( $(compgen -W "--on --off --reset -h --help" -- "$cur") )
            fi
            ;;
        logs)
            COMPREPLY=( $(compgen -W "-n --lines -f --follow --level -h --help" -- "$cur") )
            ;;
        mode)
            if [[ "$cur" != -* ]] && (( COMP_CWORD == i + 1 )); then
                COMPREPLY=( $(compgen -W "auto manual hybrid" -- "$cur") )
            else
                COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            fi
            ;;
        restart)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            ;;
        start)
            COMPREPLY=( $(compgen -W "--foreground --dry-run -h --help" -- "$cur") )
            ;;
        status)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            ;;
        stop)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            ;;
        undo)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            ;;
        uninstall-autostart)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            ;;
        verify)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            ;;
        version)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            ;;
        *)
            COMPREPLY=( $(compgen -W "-h --help --version --lang" -- "$cur") )
            ;;
    esac
    return 0
}

complete -F _klyrshift klyrshift
